    private static void StoredRar(string output)
    {
        static uint Crc(byte[] data){var crc=uint.MaxValue;foreach(var b in data){crc^=b;for(var i=0;i<8;i++)crc=(crc&1)!=0?(crc>>1)^0xedb88320:crc>>1;}return ~crc;}
        using var file=new BinaryWriter(File.Create(output));file.Write(new byte[]{0x52,0x61,0x72,0x21,0x1a,0x07,0x00});
        void Header(byte type,ushort flags,byte[] payload){using var memory=new MemoryStream();using(var header=new BinaryWriter(memory,Encoding.UTF8,true)){header.Write(type);header.Write(flags);header.Write((ushort)(7+payload.Length));header.Write(payload);}var bytes=memory.ToArray();file.Write((ushort)Crc(bytes));file.Write(bytes);}
        Header(0x73,0,new byte[6]);var data=Encoding.UTF8.GetBytes("Filevero archive fixture");var name=Encoding.ASCII.GetBytes("Fruit.txt");using var content=new MemoryStream();using(var header=new BinaryWriter(content,Encoding.UTF8,true)){header.Write((uint)data.Length);header.Write((uint)data.Length);header.Write((byte)2);header.Write(Crc(data));header.Write(0u);header.Write((byte)20);header.Write((byte)0x30);header.Write((ushort)name.Length);header.Write(0x20u);header.Write(name);}Header(0x74,0x8000,content.ToArray());file.Write(data);Header(0x7b,0,[]);
    }

    private static byte[] MinimalPdf(string content,string catalog="")
    {
        var objects=new[]{"<< /Type /Catalog /Pages 2 0 R"+catalog+" >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",$"<< /Length {content.Length} >>\nstream\n{content}\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};
        var pdf=new StringBuilder("%PDF-1.4\n");var offsets=new List<int>();
        for(var n=0;n<objects.Length;n++){offsets.Add(pdf.Length);pdf.Append($"{n+1} 0 obj\n{objects[n]}\nendobj\n");}
        var xref=pdf.Length;pdf.Append($"xref\n0 {objects.Length+1}\n0000000000 65535 f \n");foreach(var offset in offsets)pdf.Append($"{offset:D10} 00000 n \n");
        pdf.Append($"trailer\n<< /Size {objects.Length+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n");return Encoding.ASCII.GetBytes(pdf.ToString());
    }
